makeMtLab(document.getElementById("lab-l32"),{id:"l32",scenarios:[{"label": "Ví dụ: Số dòng mỗi ngày", "note": "Tag × tần suất × giây.", "steps": [{"t": "3 tag, 1 mẫu/giây", "html": "<p class=\"mt-calc\">3 × 86 400<\/p>"}, {"t": "Kết quả", "html": "<p class=\"mt-calc\"><b>259 200<\/b> dòng/ngày<\/p>", "ask": {"q": "Một năm khoảng bao nhiêu dòng?", "o": ["9,5 triệu", "94,6 triệu", "946 triệu"], "a": 1}}]}, {"label": "Ví dụ: Gộp 5 phút", "note": "1 giờ thành 12 khung.", "steps": [{"t": "3 600 mẫu khối lượng", "html": "<p class=\"mt-calc\">Một mẫu mỗi giây<\/p>"}, {"t": "time_bucket('5 minutes')", "html": "<p class=\"mt-calc\">12 dòng: trung bình, nhỏ nhất, lớn nhất<\/p>"}]}, {"label": "Ví dụ: Sự kiện không cần TimescaleDB", "note": "Vài trăm dòng mỗi ca.", "steps": [{"t": "state_event", "html": "<p class=\"mt-calc\">~50 sự kiện/máy/ca<\/p>"}, {"t": "Kết luận", "html": "<p class=\"mt-calc\">PostgreSQL thường là đủ<\/p>"}]}, {"label": "Bẫy: Lưu trạng thái mỗi giây", "note": "Biến sự kiện thành chuỗi thời gian.", "steps": [{"t": "RUN/DOWN mỗi giây cho 3 máy", "html": "<p class=\"mt-calc\">259 200 dòng/ngày thay vì ~300<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Chỉ lưu khi đổi trạng thái (Chương 12)<\/p>"}]}, {"label": "Lỗi: Không có kế hoạch xóa dữ liệu cũ", "note": "Ổ đĩa đầy.", "steps": [{"t": "Lưu mẫu theo giây 2 năm", "html": "<p class=\"mt-calc\">~189 triệu dòng, ổ đĩa đầy<\/p>"}, {"t": "Sửa", "html": "<p class=\"mt-calc\">Giữ chi tiết 90 ngày, giữ bản gộp 5 phút lâu dài<\/p>"}]}]});
makeMtEx(document.getElementById("ex-l32"),"l32",[{"kind": "num", "t": "Khối lượng dữ liệu", "d": "<p>Trả lời bằng một số.<\/p>", "items": [{"q": "5 tag, 1 mẫu/giây. Bao nhiêu dòng/ngày?", "a": 432000, "unit": "dòng"}, {"q": "1 tag, 1 mẫu mỗi 10 giây. Bao nhiêu dòng/ngày?", "a": 8640, "unit": "dòng"}, {"q": "Gộp 1 giờ theo khung 5 phút được bao nhiêu khung?", "a": 12, "unit": "khung"}], "hints": ["Một ngày có 86 400 giây.", "Chia cho chu kỳ lấy mẫu."], "why": "5 × 86 400 = 432 000; 86 400 / 10 = 8 640; 60 / 5 = 12."}, {"kind": "pick", "t": "Sự kiện hay chuỗi thời gian?", "d": "<p>Cách lưu phù hợp.<\/p>", "cats": ["Sự kiện", "Chuỗi thời gian"], "items": [{"q": "Máy đổi trạng thái", "a": 0}, {"q": "Khối lượng từng hộp ở M3", "a": 1}, {"q": "Lệnh bắt đầu", "a": 0}, {"q": "Nhiệt độ lò rang mỗi giây", "a": 1}, {"q": "Mã lỗi xuất hiện", "a": 0}], "hints": ["Ghi khi thay đổi: sự kiện.", "Ghi đều đặn: chuỗi thời gian."], "why": "Đổi trạng thái, lệnh, mã lỗi: sự kiện; khối lượng, nhiệt độ: chuỗi thời gian."}, {"kind": "order", "t": "Dùng TimescaleDB", "d": "<p>Sắp xếp.<\/p>", "items": ["CREATE EXTENSION timescaledb", "CREATE TABLE machine_sample", "create_hypertable theo cột ts", "Ghi mẫu", "Truy vấn time_bucket"], "hints": ["Cài extension trước.", "Chuyển thành hypertable trước khi ghi nhiều dữ liệu."], "why": "Extension → bảng → hypertable → ghi → gộp."}]);
mesSim(document.getElementById("sim-l32"),Object.assign({id:"l32"},{kind:"db",title:"Gộp chuỗi thời gian bằng time_bucket",sub:"Bảng machine_sample: khối lượng từng hộp ở M3 (số liệu sinh ngẫu nhiên quanh 503 g). Trình mô phỏng hỗ trợ time_bucket như TimescaleDB.",show:"machine_sample",maxRows:8,
 tables:[{name:"machine_sample",cols:[{n:"machine_id",ty:"text"},{n:"ts",ty:"timestamptz"},{n:"tag",ty:"text"},{n:"value",ty:"double"}],
  rows:(()=>{const r=[];let s=7;const rnd=()=>{s=(s*1103515245+12345)%2147483648;return s/2147483648};for(let i=0;i<360;i++){const m=i*5;const hh=8+Math.floor(m/3600),mm=Math.floor(m%3600/60),ss=m%60;
   r.push({machine_id:"L1-M3",ts:"2026-11-12 "+String(hh).padStart(2,"0")+":"+String(mm).padStart(2,"0")+":"+String(ss).padStart(2,"0"),tag:"weight_g",value:Math.round((503.3+(rnd()+rnd()+rnd()-1.5)*1.2)*10)/10})}return r})()}],
 sql:"SELECT time_bucket('5 minutes', ts) AS khung,\n  round(avg(value), 2) AS tb, min(value), max(value), count(*) AS so_hop\nFROM machine_sample\nWHERE machine_id = 'L1-M3' AND tag = 'weight_g'\nGROUP BY khung ORDER BY khung;",
 tasks:[{t:"Đếm số mẫu trong bảng (một hộp mỗi 5 giây, 30 phút).",check:(s,c)=>c.has("sql",e=>e.ok&&e.rows.length===1&&e.rows[0][0]===360)},
  {t:"Chạy truy vấn gộp 5 phút có sẵn.",ok:"360 dòng thành 6 dòng; giữ cả min, max để không mất hộp nhẹ bất thường.",check:(s,c)=>c.has("sql",e=>e.ok&&/time_bucket/.test(e.sql)&&e.rows.length===6)},
  {t:"Đổi khung thành 10 phút.",check:(s,c)=>c.has("sql",e=>e.ok&&/10 minutes/.test(e.sql)&&e.rows.length===3)}]}));

